import { describe, it, expect } from 'vitest'
import fs from 'fs'
import path from 'path'
import { fileNameForTag, formatBody, summarize, renderRelease } from '../../scripts/sync-changelog.mjs'

// /changelog mirrors the GitHub releases page from files generated by
// scripts/sync-changelog.mjs. These pin the transformations that make a GitHub
// release body safe and correct to render on our own page.

const repo = 'answerLoops/answerLoops'
const opts = { name: 'v1.2.3', tag: 'v1.2.3', repo }

describe('formatBody', () => {
  it('drops the leading heading that repeats the release name', () => {
    expect(formatBody('## v1.2.3\n\nIntro.', opts)).toBe('Intro.')
  })

  it('keeps a leading heading that is not the release name', () => {
    expect(formatBody('## Highlights\n\nIntro.', opts)).toBe('### Highlights\n\nIntro.')
  })

  it('demotes headings so the page owns h1 and h2', () => {
    const out = formatBody('Intro.\n\n# Big\n## New Contributors\n### Fixed', opts)
    expect(out).toBe('Intro.\n\n### Big\n### New Contributors\n### Fixed')
  })

  it('links PR numbers and mentions the way GitHub renders them', () => {
    const out = formatBody('Fixed a crash (#12) thanks to @octo-cat.', opts)
    expect(out).toBe(
      `Fixed a crash ([#12](https://github.com/${repo}/issues/12)) thanks to [@octo-cat](https://github.com/octo-cat).`,
    )
  })

  it('leaves code spans, existing links, bare URLs and fenced code alone', () => {
    const body = [
      'Use `#12` and `@scope/pkg` as-is.',
      'See [#7](https://example.com/#7) and https://github.com/a/b/pull/9 and @a/b-scoped.',
      '```',
      'echo "#1 @user"',
      '```',
    ].join('\n')
    expect(formatBody(body, opts)).toBe(body)
  })

  it('does not treat email addresses or anchors as mentions or PRs', () => {
    const body = 'Write to hello@example.com or jump to page#3.'
    expect(formatBody(body, opts)).toBe(body)
  })

  it('normalizes CRLF line endings and tolerates an empty body', () => {
    expect(formatBody('Line one\r\nLine two', opts)).toBe('Line one\nLine two')
    expect(formatBody(null, opts)).toBe('')
  })
})

describe('summarize', () => {
  it('uses the first prose paragraph as plain text', () => {
    const body = '### Heading\n\n**Big** news with [a link](https://x.y) and `code`.\n\n- bullet'
    expect(summarize(body, 'v1')).toBe('Big news with a link and code.')
  })

  it('falls back when there is no prose paragraph', () => {
    expect(summarize('- only\n- bullets', 'v1.0.0')).toBe('Release notes for answerLoops v1.0.0.')
  })

  it('truncates long paragraphs', () => {
    const out = summarize('word '.repeat(200), 'v1')
    expect(out.length).toBeLessThanOrEqual(300)
    expect(out.endsWith('...')).toBe(true)
  })
})

describe('renderRelease', () => {
  const release = {
    name: 'v1.2.3',
    tag_name: 'v1.2.3',
    published_at: '2026-10-24T13:12:48Z',
    created_at: '2026-10-24T13:00:00Z',
    html_url: 'https://github.com/answerLoops/answerLoops/releases/tag/v1.2.3',
    prerelease: false,
    body: '## v1.2.3\n\nHeadline "quoted" text.\n\n### Fixed\n- A thing (#5)',
  }

  it('writes parseable frontmatter followed by the adapted notes', () => {
    const out = renderRelease(release, repo)
    expect(out).toContain('tag: "v1.2.3"')
    expect(out).toContain('datePublished: "2026-10-24T13:12:48Z"')
    expect(out).toContain('prerelease: false')
    expect(out).toContain('summary: "Headline \\"quoted\\" text."')
    expect(out).toMatch(/---\n\nHeadline "quoted" text\./)
    expect(out.endsWith('\n')).toBe(true)
  })

  it('is deterministic, so a re-sync of an unchanged release writes nothing', () => {
    expect(renderRelease(release, repo)).toBe(renderRelease({ ...release }, repo))
  })

  it('still produces a body for a release with empty notes', () => {
    expect(renderRelease({ ...release, body: '' }, repo)).toContain('Release v1.2.3.')
  })
})

describe('fileNameForTag', () => {
  it('keeps normal tags and neutralizes path separators', () => {
    expect(fileNameForTag('v0.6.6')).toBe('v0.6.6.md')
    expect(fileNameForTag('../etc/passwd')).toBe('..-etc-passwd.md')
  })
})

describe('content/changelog', () => {
  const dir = path.join(process.cwd(), 'content/changelog')
  const files = fs.readdirSync(dir).filter((f) => f.endsWith('.md'))

  it('has at least one release', () => {
    expect(files.length).toBeGreaterThan(0)
  })

  it.each(files)('%s has complete frontmatter and a body', (file) => {
    const text = fs.readFileSync(path.join(dir, file), 'utf-8')
    const match = text.match(/^---\n([\s\S]*?)\n---\n\n([\s\S]+)$/)
    expect(match, 'frontmatter block then body').not.toBeNull()
    for (const key of ['title', 'tag', 'datePublished', 'url', 'prerelease', 'summary']) {
      expect(match![1], `${key} in frontmatter`).toMatch(new RegExp(`^${key}: `, 'm'))
    }
    expect(file).toBe(`${JSON.parse(match![1].match(/^tag: (.*)$/m)![1])}.md`)
  })
})
